<?php require '../config.php';$err='';if($_SERVER['REQUEST_METHOD']=='POST'){$email=$_POST['email'];$pass=$_POST['password'];$q=$db->prepare("SELECT * FROM admins WHERE email=?");$q->bind_param("s",$email);$q->execute();$a=$q->get_result()->fetch_assoc();if($a&&password_verify($pass,$a['password'])){$_SESSION['admin_id']=$a['id'];header("Location:index.php");exit;}$err="Invalid admin credentials.";}?><!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Admin Login</title><link rel="stylesheet" href="../assets/style.css"></head><body><div class="auth"><div class="auth-box"><a class="brand" href="../index.php">NWD <span>PANEL</span></a><h1>Admin Login</h1><?php if($err):?><div class="alert"><?=$err?></div><?php endif;?><form method="post"><label>Email<input type="email" name="email" value="admin@example.com" required></label><label>Password<input type="password" name="password" required></label><button class="btn primary full">Login</button></form></div></div></body></html>